src=[[0]*13 for _ in range(11)]
rows={3:[6,7,8],4:[4,5,6,8],5:[4,8],6:[4,5,8],7:[5,8,9],8:[5,9],9:[5,6,7,8,9]}
for r,cs in rows.items():
 for c in cs:src[r][c]=7
out=[[0]*13 for _ in range(11)]
for r in range(11):
 shift=9-r if r<=9 else 0
 for c,v in enumerate(src[r]):
  nc=c-shift
  if v and nc>=0:out[r][nc]=v
assert len(out)==11 and all(len(x)==13 for x in out)
print('\n'.join('['+', '.join(map(str,row))+'],' for row in out))
